param(
  [switch]$SkipBuild
)

Set-StrictMode -Version Latest
$ErrorActionPreference = "Stop"

$Root = (Get-Location).Path
$Target = Join-Path $Root "app\api\mercado-pago\webhook\route.ts"
$SubscriptionModule = Join-Path $Root "lib\payments\subscription\mercado-pago.ts"
$Stamp = Get-Date -Format "yyyyMMdd-HHmmss"
$Backup = Join-Path $Root ".orcaly-backups\reescrever-webhook-assinatura-$Stamp\route.ts"
$Utf8 = New-Object System.Text.UTF8Encoding($false)

if (-not (Test-Path -LiteralPath (Join-Path $Root "package.json"))) {
  throw "Execute este script na raiz do projeto Orcaly."
}

$Branch = (& git branch --show-current 2>$null | Out-String).Trim()

if ($Branch -ne "feature/asaas-sandbox") {
  throw "Branch atual: $Branch. Execute na branch feature/asaas-sandbox."
}

if (-not (Test-Path -LiteralPath $Target)) {
  throw "Arquivo nao encontrado: app/api/mercado-pago/webhook/route.ts"
}

if (-not (Test-Path -LiteralPath $SubscriptionModule)) {
  throw "O modulo isolado da assinatura nao existe. Nao execute este script antes do isolamento."
}

New-Item -ItemType Directory -Force -Path (Split-Path $Backup -Parent) | Out-Null
Copy-Item -LiteralPath $Target -Destination $Backup -Force

Write-Host ""
Write-Host "==================================================" -ForegroundColor Cyan
Write-Host "ORCALY - REVISAO COMPLETA DO WEBHOOK" -ForegroundColor Cyan
Write-Host "Assinatura Mercado Pago totalmente tipada" -ForegroundColor Cyan
Write-Host "==================================================" -ForegroundColor Cyan

$RouteCode = [Text.Encoding]::UTF8.GetString(
  [Convert]::FromBase64String("")
)

[IO.File]::WriteAllText(
  $Target,
  $RouteCode.TrimEnd() + "`n",
  $Utf8
)

Write-Host "[OK] webhook de assinatura reescrito por completo" -ForegroundColor Green
Write-Host "[OK] objetos remotos normalizados antes do acesso" -ForegroundColor Green
Write-Host "[OK] payment.status tratado com seguranca" -ForegroundColor Green
Write-Host "[OK] IDs e datas convertidos para string ou null" -ForegroundColor Green
Write-Host "[OK] segredo exclusivo MP_SUBSCRIPTION_WEBHOOK_SECRET mantido" -ForegroundColor Green

Write-Host ""
Write-Host "==> Verificando isolamento e referencias" -ForegroundColor Cyan

$RequiredPatterns = @(
  'getSubscriptionWebhookSecret',
  'const payment = record(authorizedPayment.payment);',
  'const subscriptionId =',
  'verifyMercadoPagoWebhookSignature',
  'mercadoPagoPlatformRequest'
)

foreach ($Pattern in $RequiredPatterns) {
  $Match = Select-String `
    -LiteralPath $Target `
    -Pattern $Pattern `
    -SimpleMatch `
    -ErrorAction SilentlyContinue

  if (-not $Match) {
    throw "Verificacao falhou: $Pattern"
  }
}

$ForbiddenPatterns = @(
  'MERCADO_PAGO_PLATFORM_ACCESS_TOKEN',
  'MERCADO_PAGO_ACCESS_TOKEN',
  'MERCADO_PAGO_WEBHOOK_SECRET',
  'NEXT_PUBLIC_MERCADO_PAGO_PUBLIC_KEY',
  'authorizedPayment?.payment?.status'
)

foreach ($Pattern in $ForbiddenPatterns) {
  $Match = Select-String `
    -LiteralPath $Target `
    -Pattern $Pattern `
    -SimpleMatch `
    -ErrorAction SilentlyContinue

  if ($Match) {
    throw "Referencia proibida encontrada: $Pattern"
  }
}

Write-Host "[OK] webhook usa somente o dominio de assinatura" -ForegroundColor Green
Write-Host "[OK] nenhuma leitura insegura de objeto remoto permaneceu" -ForegroundColor Green

if (Test-Path -LiteralPath (Join-Path $Root "scripts\auditar-isolamento-pagamentos.cjs")) {
  Write-Host ""
  Write-Host "==> Auditando os tres fluxos" -ForegroundColor Cyan

  & node (Join-Path $Root "scripts\auditar-isolamento-pagamentos.cjs")
  $AuditCode = $LASTEXITCODE

  if ($AuditCode -ne 0) {
    throw "A auditoria das variaveis isoladas falhou."
  }
}

if (-not $SkipBuild) {
  Write-Host ""
  Write-Host "==> Limpando cache do Next" -ForegroundColor Cyan
  Remove-Item -Recurse -Force (Join-Path $Root ".next") -ErrorAction SilentlyContinue

  Write-Host ""
  Write-Host "==> Executando build completo" -ForegroundColor Cyan

  & npm.cmd run build
  $BuildCode = $LASTEXITCODE

  Write-Host "BUILD_EXIT_CODE=$BuildCode"

  if ($BuildCode -ne 0) {
    Write-Host ""
    Write-Host "O webhook reescrito passou pelas verificacoes, mas o projeto possui outro erro fora deste arquivo." -ForegroundColor Red
    Write-Host "Nenhum commit foi criado." -ForegroundColor Red
    Write-Host "Backup: $Backup" -ForegroundColor Yellow
    exit $BuildCode
  }
}

Write-Host ""
Write-Host "==================================================" -ForegroundColor Magenta
Write-Host "WEBHOOK REVISADO E BUILD APROVADO" -ForegroundColor Magenta
Write-Host "==================================================" -ForegroundColor Magenta
Write-Host "Assinatura: MP_SUBSCRIPTION_*"
Write-Host "Cadastro: MP_SIGNUP_*"
Write-Host "Marketplace: MP_MARKETPLACE_* e OAuth por empresa"
Write-Host "Nenhum commit ou deploy foi criado."
Write-Host "Backup: $Backup"
